if func is None:
    return functools.partial(
        scorer, name=name, description=description, aggregations=aggregations
    )

if not callable(func):
    raise MlflowException.invalid_parameter_value(
        f"The scorer decorator expects a callable, got {type(func).__name__}."
    )

from mlflow.genai.scorers.validation import validate_aggregations

validate_aggregations(aggregations)

signature = inspect.signature(func)
allowed_inputs = {"inputs", "outputs", "expectations", "trace"}
unsupported_required_inputs = {
    parameter.name
    for parameter in signature.parameters.values()
    if parameter.kind
    not in (inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD)
    and parameter.name not in allowed_inputs
    and parameter.default is inspect.Parameter.empty
}
if unsupported_required_inputs:
    raise MlflowException.invalid_parameter_value(
        "Scorer functions may only require the following evaluation inputs: "
        f"{sorted(allowed_inputs)}. Got unsupported required parameters: "
        f"{sorted(unsupported_required_inputs)}."
    )

class CustomScorer(Scorer):
    _original_func: Callable[..., Any] = PrivateAttr()

    def __init__(self, **data):
        super().__init__(**data)
        self._original_func = func

    @functools.wraps(func)
    def __call__(self, *args, **kwargs):
        return self._original_func(*args, **kwargs)

    @property
    def kind(self) -> ScorerKind:
        return ScorerKind.DECORATOR
# Update the __call__ method's signature to match the original function
# but add 'self' as the first parameter. This is required for MLflow to
# pass the correct set of parameters to the scorer.
params = list(signature.parameters.values())
new_params = [inspect.Parameter("self", inspect.Parameter.POSITIONAL_OR_KEYWORD)] + params
new_signature = signature.replace(parameters=new_params)
CustomScorer.__call__.__signature__ = new_signature

return CustomScorer(
    name=name or func.__name__,
    description=description,
    aggregations=aggregations,
)

