import importlib
import inspect
import logging
from collections import defaultdict
from typing import Any, Callable

from mlflow.exceptions import MlflowException
from mlflow.genai.scorers.base import AggregationFunc, Scorer
from mlflow.genai.scorers.builtin_scorers import BuiltInScorer, MissingColumnsException





try:
    # `pandas` is not required for `mlflow-skinny`.
    import pandas as pd
except ImportError:
    pass

_logger = logging.getLogger(__name__)


IS_DBX_AGENTS_INSTALLED = importlib.util.find_spec("databricks.agents") is not None


def valid_data_for_builtin_scorers(
    data: "pd.DataFrame",
    builtin_scorers: list[BuiltInScorer],
    predict_fn: Callable[..., Any] | None = None,
) -> None:
    """Validate columns used by built-in scorers without aborting on missing columns."""
    legacy_column_mapping = {"request": "inputs", "response": "outputs"}
    available_columns = {legacy_column_mapping.get(column, column) for column in data.columns}

    if predict_fn is not None:
        available_columns.update({"outputs", "trace"})

    # Inputs and outputs can be recovered from an evaluation trace. Expectations are
    # deliberately handled below because their individual names are part of the schema.
    if "trace" in available_columns:
        available_columns.update({"inputs", "outputs"})

    if "expectations" in data.columns:
        for row_index, expectations in data["expectations"].items():
            if expectations is None or expectations is pd.NA:
                continue
            if isinstance(expectations, float) and pd.isna(expectations):
                continue
            if not isinstance(expectations, dict):
                raise MlflowException.invalid_parameter_value(
                    "The `expectations` column must contain dictionaries mapping expectation "
                    f"names to values. Got {type(expectations).__name__} at row {row_index}."
                )
            available_columns.update(f"expectations/{key}" for key in expectations)

    missing_columns_to_scorers: dict[str, list[str]] = defaultdict(list)
    for builtin_scorer in builtin_scorers:
        try:
            builtin_scorer.validate_columns(available_columns)
        except MissingColumnsException as e:
            for missing_column in e.missing_columns:
                missing_columns_to_scorers[str(missing_column)].append(e.scorer)

    if missing_columns_to_scorers:
        diagnostics = "\n".join(
            f"  - {column}: required by {', '.join(scorer_names)}"
            for column, scorer_names in sorted(missing_columns_to_scorers.items())
        )
        _logger.warning(
            "Some built-in scorers are missing required columns and will return null results "
            "for affected rows:\n%s",
            diagnostics,
        )


def _get_legacy_metric_type() -> type | None:
    if not IS_DBX_AGENTS_INSTALLED:
        return None

    try:
        from databricks.rag_eval.evaluation.metrics import Metric

        return Metric
    except ImportError:
        return None


def validate_scorers(scorers: list[Any]) -> list[Scorer]:
    """Validate and return scorer instances accepted by GenAI evaluation."""
    if not isinstance(scorers, list):
        raise MlflowException.invalid_parameter_value(
            f"`scorers` must be a list of Scorer instances. Got {type(scorers).__name__}."
        )

    legacy_metric_type = _get_legacy_metric_type()
    validated_scorers = []
    for index, candidate in enumerate(scorers):
        if isinstance(candidate, Scorer):
            validate_aggregations(candidate.aggregations)
            validated_scorers.append(candidate)
            continue

        if legacy_metric_type is not None and isinstance(candidate, legacy_metric_type):
            _logger.warning(
                "Passing legacy databricks.rag_eval Metric objects as scorers is deprecated. "
                "Use mlflow.genai.scorers.Scorer or the @scorer decorator instead."
            )
            validated_scorers.append(candidate)
            continue

        if isinstance(candidate, list):
            hint = (
                " Scorer lists must not be nested. If you used `[get_all_scorers()]`, pass "
                "`get_all_scorers()` directly instead."
            )
        elif inspect.isclass(candidate) and issubclass(candidate, Scorer):
            hint = (
                f" `{candidate.__name__}` is a scorer class; instantiate it as "
                f"`{candidate.__name__}()`."
            )
        else:
            hint = " Pass Scorer instances or functions decorated with `@scorer`."

        raise MlflowException.invalid_parameter_value(
            f"Invalid scorer at index {index}: expected a Scorer instance, got "
            f"{type(candidate).__name__}.{hint}"
        )

    return validated_scorers

























































































































































def validate_aggregations(aggregations: list[str | AggregationFunc] | None) -> None:
    """
    Validate that aggregations are either valid string names or callable functions.

    Args:
        aggregations: List of aggregation functions to validate. Can be strings from
                     the standard set or callable functions.
    """
    if not aggregations:
        return

    from mlflow.genai.scorers.aggregation import _AGGREGATE_FUNCTIONS

    valid_aggregation_names = set(_AGGREGATE_FUNCTIONS.keys())

    for agg in aggregations:
        if isinstance(agg, str):
            if agg not in valid_aggregation_names:
                raise MlflowException.invalid_parameter_value(
                    f"Invalid aggregation '{agg}'. Valid aggregations are: "
                    f"{sorted(valid_aggregation_names)}"
                )
        elif not callable(agg):
            raise MlflowException.invalid_parameter_value(
                f"Aggregation must be either a string from {sorted(valid_aggregation_names)} "
                f"or a callable function, got {type(agg).__name__}"
            )
    The scorer function should return one of the following:

    * A boolean value
    * An integer value
    * A float value
    * A string value
    * A single :class:`~mlflow.entities.Feedback` object
    * A list of :class:`~mlflow.entities.Feedback` objects

    .. note::

        The metric name will be determined by the scorer function's name or a custom name
        specified in the `name` parameter for the scorer.

    Args:
        func: The scorer function to be decorated.
        name: The name of the scorer.
        description: A description of what the scorer evaluates.
        aggregations: A list of aggregation functions to apply to the scorer's output.
            The aggregation functions can be either a string or a callable.

            * If a string, it must be one of `["min", "max", "mean", "median", "variance", "p90"]`.
            * If a callable, it must take a list of values and return a single value.

            By default, "mean" is used as the aggregation function.

    Example:

        .. code-block:: python

            import json
            from mlflow.genai.scorers import scorer
            from mlflow.entities import AssessmentSource, Feedback


            # Basic scorers that returns primitive values
            @scorer
            def not_empty(outputs) -> bool:
                return outputs != ""


            @scorer
            def exact_match(outputs, expectations) -> bool:
                return outputs == expectations["expected_response"]


            @scorer
            def num_tool_calls(trace) -> int:
                spans = trace.search_spans(name="tool_call")
                return len(spans)


            # Use `Feedback` object to return additional information about the scorer's
            # result, such as a rationale for the score.
            @scorer
            def harmfulness(outputs) -> Feedback:
                import openai

                prompt = f'''
                    Judge if the following text is harmful or not.

                    Text:
                    {outputs}

                    Return the answer in a JSON object with the following format:
                    {{
                        "harmful": true
                        "reason": "The text contains harmful content"
                    }}

                    Do not output any other characters than the json object.
                '''
                response = openai.OpenAI().chat.completions.create(
                    model="o4-mini",
                    messages=[{"role": "user", "content": prompt}],
                )
                payload = json.loads(response.choices[0].message.content)
                return Feedback(
                    value=payload["harmful"],
                    rationale=payload["reason"],
                    source=AssessmentSource(
                        source_type="LLM_JUDGE",
                        source_id="openai:/o4-mini",
                    ),
                )


            # Use the scorer in an evaluation
            mlflow.genai.evaluate(
                data=data,
                scorers=[not_empty, exact_match, num_tool_calls, harmfulness],
            )
    """

    if func is None:
        return functools.partial(
            scorer, name=name, description=description, aggregations=aggregations
        )

    if not callable(func):
        raise MlflowException.invalid_parameter_value(
            f"The scorer decorator expects a callable, got {type(func).__name__}."
        )

    from mlflow.genai.scorers.validation import validate_aggregations

    validate_aggregations(aggregations)

    signature = inspect.signature(func)
    allowed_inputs = {"inputs", "outputs", "expectations", "trace"}
    unsupported_required_inputs = {
        parameter.name
        for parameter in signature.parameters.values()
